function validate(input) {
  const [{ Users = [] }] = input;
  for (const [user, item, created] of Users) {
    if (user === null || item === null) return 'Every purchase needs a user_id and an item.';
    if (typeof created !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(created)) return `A purchase of user ${user} needs a created_at date like 2021-09-18.`;
  }
  return null;
}

