WITH purchases AS (
  SELECT user_id, created_at,
    LAG(created_at) OVER (
      PARTITION BY user_id ORDER BY created_at
    ) AS prev_date
  FROM Users
)
SELECT DISTINCT user_id
FROM purchases
WHERE DATEDIFF(created_at, prev_date) <= 7;

