function generate(rand, size) {
  const small = size === 'small';
  const day = offset => new Date(Date.UTC(2021, 8, 1) + offset * 86400000).toISOString().slice(0, 10);
  const items = ['Smart Lock', 'Smart Bed', 'Smart Crock Pot', 'Smart Thermostat', 'Smart Light Strip', 'Smart Cat Feeder'];
  const count = small ? Math.floor(rand() * 9) : 2000;
  const users = small ? 4 : 400, span = small ? 24 : 365;
  const Users = [];
  while (Users.length < count) {
    // Now and then repeat an earlier row, since the table may hold duplicates.
    if (Users.length && rand() < 0.1) { Users.push([...Users[Math.floor(rand() * Users.length)]]); continue; }
    Users.push([1 + Math.floor(rand() * users), items[Math.floor(rand() * items.length)], day(Math.floor(rand() * span)), 1000 + Math.floor(rand() * 700000)]);
  }
  return [{ Users }];
}
